macro_rules! deps {
    () => {
        Literal!();
    };
}

macro_rules! ParseErrorKind {
    () => {
        deps!();
        # [doc = " Kinds of errors."] # [derive (Debug , Clone , Copy , PartialEq , Eq)] # [non_exhaustive] pub (crate) enum ParseErrorKind { # [doc = " The input was an empty string"] Empty , # [doc = " An unexpected char was encountered."] UnexpectedChar , # [doc = " Literal was not recognized."] InvalidLiteral , # [doc = " Input does not start with decimal digit when trying to parse an integer."] DoesNotStartWithDigit , # [doc = " A digit invalid for the specified integer base was found."] InvalidDigit , # [doc = " Integer literal does not contain any valid digits."] NoDigits , # [doc = " Exponent of a float literal does not contain any digits."] NoExponentDigits , # [doc = " An unknown escape code, e.g. `\\b`."] UnknownEscape , # [doc = " A started escape sequence where the input ended before the escape was"] # [doc = " finished."] UnterminatedEscape , # [doc = " An `\\x` escape where the two digits are not valid hex digits."] InvalidXEscape , # [doc = " A string or character literal using the `\\xNN` escape where `NN > 0x7F`."] NonAsciiXEscape , # [doc = " A `\\u{...}` escape in a byte or byte string literal."] UnicodeEscapeInByteLiteral , # [doc = " A Unicode escape that does not start with a hex digit."] InvalidStartOfUnicodeEscape , # [doc = " A `\\u{...}` escape that lacks the opening brace."] UnicodeEscapeWithoutBrace , # [doc = " In a `\\u{...}` escape, a non-hex digit and non-underscore character was"] # [doc = " found."] NonHexDigitInUnicodeEscape , # [doc = " More than 6 digits found in unicode escape."] TooManyDigitInUnicodeEscape , # [doc = " The value from a unicode escape does not represent a valid character."] InvalidUnicodeEscapeChar , # [doc = " A `\\u{..` escape that is not terminated (lacks the closing brace)."] UnterminatedUnicodeEscape , # [doc = " A character literal that's not terminated."] UnterminatedCharLiteral , # [doc = " A character literal that contains more than one character."] OverlongCharLiteral , # [doc = " An empty character literal, i.e. `''`."] EmptyCharLiteral , UnterminatedByteLiteral , OverlongByteLiteral , EmptyByteLiteral , NonAsciiInByteLiteral , # [doc = " A `'` character was not escaped in a character or byte literal, or a `\"`"] # [doc = " character was not escaped in a string or byte string literal."] UnescapedSingleQuote , # [doc = " A \\n, \\t or \\r raw character in a char or byte literal."] UnescapedSpecialWhitespace , # [doc = " When parsing a character, byte, string or byte string literal directly"] # [doc = " and the input does not start with the corresponding quote character"] # [doc = " (plus optional raw string prefix)."] DoesNotStartWithQuote , # [doc = " Unterminated raw string literal."] UnterminatedRawString , # [doc = " String literal without a `\"` at the end."] UnterminatedString , # [doc = " Invalid start for a string literal."] InvalidStringLiteralStart , # [doc = " Invalid start for a byte literal."] InvalidByteLiteralStart , InvalidByteStringLiteralStart , # [doc = " Not starting with `c\"` or `cr`."] InvalidCStringLiteralStart , # [doc = " A `\\0` escape inside a C string."] DisallowedNulEscape , # [doc = " A nul byte inside a C String."] NulByte , # [doc = " `\\r` in a (raw) string or (raw) byte string literal."] CarriageReturn , # [doc = " Rust only allows 256 hashes in raw * string literals."] TooManyHashes , # [doc = " Literal suffix is not a valid identifier."] InvalidSuffix , # [doc = " Returned by `Float::parse` if an integer literal (no fractional nor"] # [doc = " exponent part) is passed."] UnexpectedIntegerLit , # [doc = " Integer suffixes cannot start with `e` or `E` as this conflicts with the"] # [doc = " grammar for float literals."] IntegerSuffixStartingWithE , }
    };
}

ParseErrorKind!()